type JsonLd = Record<string, any>;

function buildJsonLd(params: {
  siteUrl: string;
  pageUrl: string;
  lang: string;
  title: string;
  description: string;
  providerName: string;
  providerUrl: string;
  areaServed: string[];
  offers: { name: string; description: string }[];
}): JsonLd[] {
  const {
    siteUrl,
    pageUrl,
    lang,
    title,
    description,
    providerName,
    providerUrl,
    areaServed,
    offers,
  } = params;

  const service = {
    "@context": "https://schema.org",
    "@type": "Service",
    "@id": `${pageUrl}#service`,
    "name": title,
    "description": description,
    "provider": {
      "@type": "Person",
      "name": providerName,
      "url": providerUrl,
    },
    "areaServed": areaServed.map((name) => ({ "@type": "AdministrativeArea", name })),
    "availableChannel": {
      "@type": "ServiceChannel",
      "serviceUrl": pageUrl,
    },
    "offers": offers.map((o, i) => ({
      "@type": "Offer",
      "@id": `${pageUrl}#offer-${i + 1}`,
      "name": o.name,
      "description": o.description,
      "url": pageUrl,
      "priceCurrency": "CAD",
    })),
    "inLanguage": lang,
  };

  const breadcrumb = {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    "@id": `${pageUrl}#breadcrumbs`,
    "itemListElement": [
      { "@type": "ListItem", position: 1, name: "Home", item: siteUrl },
      { "@type": "ListItem", position: 2, name: "Services", item: `${siteUrl}/services/` },
      { "@type": "ListItem", position: 3, name: title, item: pageUrl },
    ],
  };

  return [service, breadcrumb];
}

